import { InternedStringRef } from "./intern-interface";

export const domNodeSymbol = Symbol("domNode");

export type DomTextNode = {
    text: string;
};
export type DomNode = {
    r: object; // ref
    t?: string; // tag
    c?: DomNode[]; // children
    parent?: DomNode; // parent node (set by renderer on insert, cleared on remove)
    _s?: typeof domNodeSymbol;
    p?: InternedProps; // props. Not filled at the moment for anchor nodes
    focus?: () => void; // focus method
    blur?: () => void; // blur method
};

export type PropValue = number | string | boolean | null | { [key: string]: PropValue } | PropValue[];
export type PropOutputValue = (p: PropValue) => void;
export type InternedProps = { [key: number]: PropValue };
export type InternedOutputs = { [key: number]: PropOutputValue };
export type OutputHandler<T = PropValue | AnchorNodeFieldValueType> = (p: T) => void;

export interface AnchorNode extends DomNode {
    o?: InternedOutputs; // outputs. Not filled at the moment
    n: InternedStringRef; // name
    canReceiveFocus?: boolean; // true if the anchor node extends a focusable type (e.g. FocusBoundaryBase)
}

export type Intern = {
    getInternedStringRef: (str: string) => InternedStringRef | undefined;
    internString: (str: string) => InternedStringRef;
};

export type AnchorNodeFieldValueType =
    number | string | boolean | null | AnchorNodeFieldValueObject | AnchorNodeFieldValueArray;
export type AnchorNodeFieldValueArray = AnchorNodeFieldValueType[];
export type AnchorNodeFieldValueObject = { [key: string]: AnchorNodeFieldValueType | undefined };

// Fn that returns a default value for a field
export type AnchorNodeDefaultValueFn<T extends AnchorNodeFieldValueType = AnchorNodeFieldValueType> = (() => T) & {
    isFloat?: boolean;
};

export const AnchorNodeFieldTypes = {
    Null: (): AnchorNodeDefaultValueFn<null> => () => null,
    Boolean:
        (d: boolean = true): AnchorNodeDefaultValueFn<boolean> =>
        () =>
            d,
    Number:
        (d: number = 0): AnchorNodeDefaultValueFn<number> =>
        () =>
            d,
    Float: (d: number = 0): AnchorNodeDefaultValueFn<number> => {
        const fn: AnchorNodeDefaultValueFn<number> = () => d;
        fn.isFloat = true;
        return fn;
    },
    String:
        (d: string = ""): AnchorNodeDefaultValueFn<string> =>
        () =>
            d,
    Array:
        (d: AnchorNodeFieldValueArray = []): AnchorNodeDefaultValueFn<AnchorNodeFieldValueArray> =>
        () =>
            d,
    Object:
        <T extends AnchorNodeFieldValueObject>(d: T = {} as T): AnchorNodeDefaultValueFn<T> =>
        (): T =>
            d
};

export type AnchorNodeGetDefaultValueFn<T extends AnchorNodeFieldValueType> = (d: T) => T;
export type AnchorNodeDefaultValueMap = Record<string, AnchorNodeDefaultValueFn>;
export type AnchorNodeExtractInputFields<T> = {
    [K in keyof T]: T[K] extends AnchorNodeGetDefaultValueFn<infer U> ? U : never;
};
export type AnchorNodeExtractOutputFields<T> = {
    [K in keyof T]: T[K] extends AnchorNodeGetDefaultValueFn<infer U> ? OutputHandler<U> : never | null;
};

export type ComponentRef<T> = DomNode & Partial<T>;

/**
 * Represents a typed XML component import.
 * When a `.xml` file is imported, the default export is typed as `TypedXmlComponent`
 * which carries the component name as a string literal type and the component's
 * interface field definitions as a type parameter.
 *
 * @template Name - The component name string literal (e.g., "focusable", "modal")
 * @template Fields - An interface describing the component's `<interface>` field definitions
 *
 * @example
 * ```typescript
 * // Auto-generated from focusable.xml
 * declare const _default: TypedXmlComponent<"focusable", { nextFocusUp: string; hasPreferredFocus: boolean }>;
 * export default _default;
 * ```
 */
export type TypedXmlComponent<
    Name extends string = string,
    Fields extends Record<string, unknown> = Record<string, unknown>
> = Name & {
    readonly __componentName: Name;
    readonly __fields: Fields;
};
