import { logger } from "@roku-sdk/common";
import { TransactionApi } from "@roku-sdk/interfaces";

type Transaction =
    | {
          inTransaction: boolean;
      }
    | undefined;

let transactionApi: TransactionApi | undefined;
let transaction: Transaction = undefined;
const precommitHooks: (() => void)[] = [];
const transactionStartHooks: (() => void)[] = [];

const txLogger = logger.getLogger("tx");

export function registerTransactionApi(incomingTransactionApi: TransactionApi) {
    transactionApi = incomingTransactionApi;
}

export function registerPreCommitHook(preCommitHook: () => void) {
    precommitHooks.push(preCommitHook);
}

export function registerTransactionStartHook(transactionStartHook: () => void) {
    transactionStartHooks.push(transactionStartHook);
}
let txFlowId: number | undefined;

function getTransactionManager() {
    const commit = () => {
        if (!transaction || !transaction.inTransaction) {
            txLogger.warn(() => "No transaction in progress to commit.");
            return;
        }
        precommitHooks.forEach(hook => {
            hook();
        });
        ;
        const txFlowIdToEnd = txFlowId;
        if (txFlowIdToEnd !== undefined) {
            roku.perfetto?.flowEvent(txFlowIdToEnd, "transaction.commit");
        }
        transactionApi?.end(txFlowIdToEnd);
        txFlowId = undefined;
        transaction = undefined;
    };

    const startTransaction = () => {
        if (!transaction) {
            txFlowId = Math.floor(Math.random() * 0x7fffffff);
            roku.perfetto?.flowEvent(txFlowId, "transaction.start");
            ;
            transactionApi?.start();
            transactionStartHooks.forEach(hook => {
                hook();
            });
            transaction = { inTransaction: true };
            Promise.resolve().then(commit);
        }
        return transaction;
    };

    return {
        startTransaction,
        inTransaction: () => {
            return transaction?.inTransaction;
        },
        commitEarly: () => {
            // only call from unit tests
            commit();
        }
    };
}

export const transactionManager = getTransactionManager();
