import { InternedStringRef, InternStringApi } from "@roku-sdk/interfaces";

let internStringApi: InternStringApi | undefined;
let reverseMap: Map<InternedStringRef, string> | undefined;
let forwardMap: Map<string, InternedStringRef> | undefined;

export function registerInternStringApi(i: InternStringApi) {
    reverseMap = new Map<InternedStringRef, string>();
    forwardMap = new Map<string, InternedStringRef>();
    internStringApi = i;
}

function assertInternStringApi() {
    if (!internStringApi) {
        throw new Error("InternStringApi not registered");
    }
}

export const stringInterner = {
    internString: (str: string) => {
        // TODO: profile this map and move it to the native side if needed
        assertInternStringApi();
        let ref = forwardMap!.get(str);
        if (ref) {
            return ref;
        }
        ref = internStringApi!.internString(str);
        forwardMap!.set(str, ref);
        reverseMap!.set(ref, str);
        return ref;
    },
    getStringByInternedRef: (ref: InternedStringRef): string => {
        assertInternStringApi();
        const str = reverseMap!.get(ref);
        if (!str) {
            throw new Error(`String for ref ${ref} not found`);
        }
        return str;
    }
};
