const bootstrapLogger = logger.getLogger("btstp");

type Destructor = () => void;
type Constructor = (anchorNode: AnchorNode) => Destructor;

type UpdateInputs = (input: InternedStringRef, value: PropValue) => void;
type UpdateOutputs = (output: InternedStringRef, handler: OutputHandler) => void;

const disposeMap = new Map<AnNodeRef, Destructor>();

/**
 * Type definition for AnchorNode component descriptors.
 *
 * An AnchorNode component descriptor defines the structure and interface of a custom
 * SceneGraph component, including its name, base type, and input/output fields.
 *
 * @property {string} componentName - Unique identifier for the component
 * @property {string} extends - Base SceneGraph component type to extend (e.g., "Group", "ContentNode").
 * @property {AnchorNodeDefaultValueMap} inputFields - Map of input field names to default values
 * @property {AnchorNodeDefaultValueMap} outputFields - Map of output field names to default values
 * @property {string} [registry] - Optional registry identifier for component organization
 *
 * @example
 * ```typescript
 * const MyComponentDescriptor = {
 *     componentName: "MyComponent",
 *     extends: "Group" as const,
 *     inputFields: {
 *         title: FieldType.String(""),
 *         visible: FieldType.Boolean(true)
 *     },
 *     outputFields: {
 *         onReady: FieldType.Boolean()
 *     }
 * };
 * ```
 */
export type AnchorNodeDescriptor = {
    componentName: string;
    extends: string;
    inputFields: AnchorNodeDefaultValueMap;
    outputFields: AnchorNodeDefaultValueMap;
    libraryName?: string;
};

/**
 * @deprecated Use `AnchorNodeDescriptor` instead. This type alias will be removed in a future release.
 * Defines the structure for declaring a TypeScript component that can be used in RSG 2.0 SDK.
 *
 * This declaration is used with `declareTsComponent()` to register a TypeScript component
 * that can interoperate with BrightScript components through input/output field communication.
 *
 * @example
 * ```typescript
 * export const BoTheCowboyDescription = {
 *     componentName: "BoTheCowboy",
 *     extends: "Group",
 *     inputFields: {
 *         wave: FieldType.Boolean()
 *     },
 *     outputFields: {
 *         isSpeaking: FieldType.Boolean()
 *     }
 * };
 *
 * export const BoTheCowboy: TsComponent<typeof BoTheCowboyDescription> = (inputs, outputs) => {
 *     return (
 *         <group>
 *             <rectangle translation={inputs.wave ? [17, 145] : [17, 180]} />
 *         </group>
 *     );
 * };
 *
 * declareTsComponent(BoTheCowboyDescription, BoTheCowboy);
 * ```
 *
 * @property {string} componentName - Unique name for the component (e.g., "BoTheCowboy")
 * @property {string} extends - Base SceneGraph component type to extend (e.g., "Group", "ContentNode").
 * @property {AnchorNodeDefaultValueMap} inputFields - Map of input field names to their default value functions.
 *   Input fields are set from BrightScript code or XML (the host). Use FieldType helpers
 *   (e.g., FieldType.Boolean(), FieldType.String()) to define field types
 * @property {AnchorNodeDefaultValueMap} outputFields - Map of output field names to their default value functions.
 *   Output fields are signals that the component can emit to communicate state changes to the
 *   BrightScript host container
 *
 */
export type TsComponentDeclaration = AnchorNodeDescriptor;

type AnchorNodeExtractInputSignals<T> = {
    [K in keyof T]: T[K] extends AnchorNodeGetDefaultValueFn<infer U> ? Signal<U> : never;
};

type AnchorNodeInputs<InputFields> = Partial<AnchorNodeExtractInputFields<InputFields>>;
type AnchorNodeOutputs<OutputFields> = AnchorNodeExtractOutputFields<OutputFields>;

const tsComponentConstructors = new Map<string, Constructor>();
const tsComponentUpdateInputs = new Map<AnNodeRef, UpdateInputs>();
const tsComponentUpdateOutputs = new Map<AnNodeRef, UpdateOutputs>();

// Tracks which anchor node component names can receive focus (extend FocusBoundaryBase).
const focusCapableComponents = new Set<string>();

/**
 * Returns true if the component registered under `name` extends a focusable base type (e.g. FocusBoundaryBase).
 * Only direct inheritance is checked — multi-level chains are not resolved.
 */
export function canComponentReceiveFocus(name: string): boolean {
    return focusCapableComponents.has(name);
}

/**
 * Type definition for AnchorNode component implementations.
 *
 * An AnchorNode implementation is a function that receives reactive input fields
 * and output signal handlers, returning JSX that defines the component's structure.
 *
 * @template T - The AnchorNodeDescriptor type defining the component's structure
 * @param inputs - Reactive input fields from the component descriptor
 * @param outputs - Output signal handlers for emitting events to BrightScript
 * @returns JSX.Element or DomNode representing the component's visual structure
 *
 * @example
 * ```typescript
 * const MyComponent: AnchorNodeImplementation<typeof MyComponentDescriptor> =
 *     (inputs, outputs) => {
 *         onMount(() => outputs.onReady(true));
 *         return <group><label text={inputs.title} /></group>;
 *     };
 * ```
 */
export type AnchorNodeImplementation<T extends AnchorNodeDescriptor> = (
    inputs: AnchorNodeInputs<T["inputFields"]>,
    outputs: AnchorNodeOutputs<T["outputFields"]>
) => DomNode | JSX.Element;

/**
 * @deprecated Use `AnchorNodeImplementation` instead. This type alias will be removed in a future release.
 * Function type for defining TypeScript components in RSG 2.0 SDK.
 *
 * A TsComponent receives reactive input fields and output signal handlers, and returns
 * JSX elements that define the component's visual structure. The component can access
 * input values reactively and emit output events to communicate with the BrightScript
 * host container.
 *
 * @template T - The TsComponentDeclaration type that defines the component's structure
 *
 * @param inputs - Reactive input fields defined in the component declaration. Access these
 *   values directly (e.g., `inputs.wave`) to respond to changes from the BrightScript host
 * @param outputs - Output signal handlers defined in the component declaration. Call these
 *   functions (e.g., `outputs.isSpeaking(true)`) to emit events to the BrightScript host container
 *
 * @returns JSX.Element or DomNode representing the component's visual structure
 *
 * @example
 * ```typescript
 * export const MyComponent: TsComponent<typeof MyComponentDescription> = (inputs, outputs) => {
 *     const [localState, setLocalState] = createSignal(false);
 *
 *     onMount(() => {
 *         // Emit output event
 *         outputs.ready(true);
 *     });
 *
 *     return (
 *         <group>
 *             <label text={inputs.title || "Default"} />
 *             <rectangle visible={inputs.showRect} />
 *         </group>
 *     );
 * };
 * ```
 *
 */
export type TsComponent<T extends TsComponentDeclaration> = (
    inputs: AnchorNodeInputs<T["inputFields"]>,
    outputs: AnchorNodeOutputs<T["outputFields"]>
) => DomNode | JSX.Element;
let declareApi: ComponentDeclaration | undefined = undefined;

/**
 * Registers a TypeScript component with RSG 2.0 SDK runtime, making it available for use
 * from BrightScript code.
 *
 * This function must be called within the `main()` callback to properly register the component
 * with the underlying SceneGraph system. Once registered, the component can be instantiated
 * from BrightScript using `createObject()` or referenced in .xml components (compiled components).
 *
 * The function handles:
 * - Component registration with the SceneGraph system
 * - Field declaration (input and output fields with proper types)
 * - Reactive input/output binding for cross-language communication
 * - Component lifecycle management
 *
 * @template T - The TsComponentDeclaration type defining the component structure
 *
 * @param declaration - The component declaration object defining componentName, extends,
 *   inputFields, and outputFields
 * @param Component - The TsComponent implementation function that renders the component
 *
 * @throws {Error} If called before setUp() has been invoked
 *
 * @example
 * ```typescript
 * // Define the component declaration
 * export const MyComponentDescription = {
 *     componentName: "MyComponent",
 *     extends: "Group",
 *     inputFields: {
 *         title: FieldType.String(),
 *         count: FieldType.Integer()
 *     },
 *     outputFields: {
 *         selected: FieldType.Boolean()
 *     }
 * };
 *
 * // Implement the component
 * export const MyComponent: TsComponent<typeof MyComponentDescription> = (inputs, outputs) => {
 *     return (
 *         <group>
 *             <label text={inputs.title} />
 *         </group>
 *     );
 * };
 *
 * // Register the component
 * main(() => {
 *     declareTsComponent(MyComponentDescription, MyComponent);
 * });
 * ```
 *
 * @remarks
 * After registration, the component can be used in BrightScript:
 * ```brightscript
 * myComp = CreateObject("roSGNode", "MyComponent")
 * myComp.title = "Hello"
 * myComp.observeField("selected", "onSelected")
 * ```
 */
export function declareTsComponent<T extends TsComponentDeclaration>(declaration: T, Component: TsComponent<T>) {
    if (!declareApi) {
        throw new Error("Declare API is not set. Make sure setUp is called first");
    }
    const componentNameRef = stringInterner.internString(declaration.componentName);
    // Keep the descriptor stable while selecting the firmware base at registration.
    // The XML shim has a distinct name so it cannot shadow the native component.
    const base =
        declaration.extends === "FocusBoundaryBase" && !hasFeature("focusBoundaryBase")
            ? "FocusBoundaryBaseShim"
            : declaration.extends;
    const extendsRef = stringInterner.internString(base);
    if (declaration.libraryName) {
        const libraryNameRef = stringInterner.internString(declaration.libraryName);
        declareApi.declareComponent(componentNameRef, extendsRef, libraryNameRef);
    } else {
        declareApi.declareComponent(componentNameRef, extendsRef);
    }

    // NOTE: We currently only check direct inheritance for focus capability (i.e. whether the component directly extends FocusBoundaryBase).
    // In the future, we will find different ways to track focus capable anchor nodes.
    if (base === "FocusBoundaryBase" || base === "FocusBoundaryBaseShim") {
        focusCapableComponents.add(declaration.componentName);
    }
    const declareFields = (fields: AnchorNodeDefaultValueMap, output: boolean) => {
        Object.keys(fields).forEach(key => {
            const fieldRef = stringInterner.internString(key);
            const defaultValueFn = fields[key];
            if (defaultValueFn === undefined) {
                return;
            }
            const defaultValue = defaultValueFn();
            switch (typeof defaultValue) {
                case "string":
                    declareApi!.addStringField(componentNameRef, fieldRef, true, output);
                    break;
                case "number":
                    if (defaultValueFn.isFloat) {
                        declareApi!.addFloatField(componentNameRef, fieldRef, true, output);
                    } else {
                        declareApi!.addIntField(componentNameRef, fieldRef, true, output);
                    }
                    break;
                case "boolean":
                    declareApi!.addBooleanField(componentNameRef, fieldRef, true, output);
                    break;
                case "object":
                    if (Array.isArray(defaultValue)) {
                        declareApi!.addArrayField(componentNameRef, fieldRef, true, output);
                    } else {
                        declareApi!.addObjectField(componentNameRef, fieldRef, true, output);
                    }
                    break;
                default:
                    throw new Error("Unsupported field type");
            }
        });
    };
    declareFields(declaration.inputFields, false);
    declareFields(declaration.outputFields, true);

    function constructComponent(anchorNode: AnchorNode): Destructor {
        const { renderer } = solidRenderer;
        const { render } = renderer;

        type InputFields = typeof declaration.inputFields;
        type ComponentProps = AnchorNodeInputs<InputFields>;
        const inputs: ComponentProps = {};
        const signals: Partial<AnchorNodeExtractInputSignals<InputFields>> = {};
        const inputFields = declaration.inputFields;
        for (const key in inputFields) {
            const defaultValueFn = inputFields[key];
            if (defaultValueFn === undefined) {
                continue;
            }
            const defaultValue = defaultValueFn();
            const signal = createSignal(defaultValue as ReturnType<InputFields[typeof key]>);
            signals[key] = signal;
            Object.defineProperty(inputs, key, {
                get: signal[0],
                enumerable: true,
                configurable: true
            });
        }

        type OutputFields = typeof declaration.outputFields;
        const outputFields: AnchorNodeOutputs<OutputFields> = {};
        for (const key in declaration.outputFields) {
            outputFields[key] = (() => {
                // does nothing if the output field has not been observed by the client
            }) as AnchorNodeExtractOutputFields<OutputFields>[typeof key];
        }
        const updateInputs = (inputFieldName: InternedStringRef, value: PropValue) => {
            const fieldName = stringInterner.getStringByInternedRef(inputFieldName);
            ;



            if (fieldName) {
                if (signals[fieldName]) {
                    const [, setSignal] = signals[fieldName];
                    // eslint-disable-next-line @typescript-eslint/no-unused-vars
                    setSignal(prev => value);
                }
            }
        };
        const updateOutputs = (outputFieldName: InternedStringRef, handler: OutputHandler) => {
            const fieldName = stringInterner.getStringByInternedRef(outputFieldName);
            if (fieldName) {
                if (outputFields[fieldName]) {
                    outputFields[fieldName] = handler;
                }
            }
        };

        tsComponentUpdateInputs.set(anchorNode.r, updateInputs);
        tsComponentUpdateOutputs.set(anchorNode.r, updateOutputs);

        const { registerAnchorNodeEventListener } = anchorNodeManipulationApi;
        for (const key in declaration.outputFields) {
            // NOTE: registerAnchorNodeEventListener is not called from native side
            // ideally we want it to be called when output field is observed from brightscript side
            registerAnchorNodeEventListener(anchorNode.r, stringInterner.internString(key));
        }

        const dispose = render(() => {
            // In dev builds, label this anchor's root owner with the component name using
            // Solid's standard dev `name` convention — devtools read it to title the
            // subtree. DEV is undefined in production builds.
            if (DEV) {
                const owner = getOwner() as { name?: string } | null;
                if (owner) {
                    owner.name = declaration.componentName;
                }
            }
            return (
                <ErrorBoundary
                    fallback={err => {
                        bootstrapLogger.error(() =>
                            ["Error in TS component: ", err.message, "\n", String(err.stack ?? "")].join("")
                        );
                        return null;
                    }}
                >
                    {untrack(() => Component(inputs, outputFields) as JSX.Element)}
                </ErrorBoundary>
            ) as unknown as DomNode;
            // return Component(inputs, outputFields) as DomNode
        }, anchorNode);

        disposeMap.set(anchorNode.r, dispose);
        ;

        return () => {
            const { unregisterAnchorNodeEventListener } = anchorNodeManipulationApi;
            for (const key in declaration.outputFields) {
                unregisterAnchorNodeEventListener(anchorNode.r, stringInterner.internString(key));
            }

            const dispose = disposeMap.get(anchorNode.r);
            ;
            if (dispose) {
                dispose();
            }
            disposeMap.delete(anchorNode.r);
            tsComponentUpdateInputs.delete(anchorNode.r);
            tsComponentUpdateOutputs.delete(anchorNode.r);
        };
    }

    tsComponentConstructors.set(declaration.componentName, constructComponent);
}

/**
 * Creates a properly-typed anchor node definition tuple for use with `registerAnchorNode`.
 *
 * This helper function provides type safety and IDE autocomplete when defining AnchorNode
 * components. It's the recommended way to declare components in modern RSG 2.0 SDK code.
 *
 * @template T - The AnchorNodeDescriptor type
 * @param description - Component descriptor defining name, base type, and fields
 * @param component - Component implementation function
 * @returns Tuple containing the descriptor and implementation
 *
 * @example
 * ```typescript
 * export default defineAnchorNode(MyComponentDescriptor, MyComponent);
 *
 * // In index.ts:
 * import { registerAnchorNode } from "@roku-sdk/rsg-ts";
 * import MyComponent from "./components/my-component";
 * registerAnchorNode(MyComponent);
 * ```
 *
 * @see registerAnchorNode - Registers the anchor node with the runtime
 * @see declareTsComponent - Alternative registration API (deprecated)
 */
export function defineAnchorNode<T extends AnchorNodeDescriptor>(
    description: T,
    component: AnchorNodeImplementation<T>
): [T, AnchorNodeImplementation<T>] {
    return [description, component];
}

/**
 * Registers an AnchorNode component using a tuple parameter pattern.
 *
 * This function is the recommended way to register components defined with `defineAnchorNode`.
 * It accepts a single tuple parameter containing both the component descriptor and implementation.
 *
 * @template T - The AnchorNodeDescriptor type
 * @param tuple - Tuple containing [descriptor, implementation] created by defineAnchorNode
 *
 * @example
 * ```typescript
 * // component.tsx
 * export default defineAnchorNode(MyDescriptor, MyImplementation);
 *
 * // index.ts
 * import { registerAnchorNode, main } from "@roku-sdk/rsg-ts";
 * import MyComponent from "./components/my-component";
 *
 * main(() => {
 *     registerAnchorNode(MyComponent);
 * });
 * ```
 *
 * @see defineAnchorNode - Helper to create typed anchor node tuples
 * @see declareTsComponent - Alternative registration API (deprecated)
 */
export const registerAnchorNode = <T extends AnchorNodeDescriptor>([declaration, Component]: [
    declaration: T,
    Component: AnchorNodeImplementation<T>
]) => declareTsComponent(declaration, Component);

// NOTE: There is only solid renderer.
// Render need to called with different anchor nodes as root
export function constructor(anchorNode: AnchorNode): Destructor {
    ;

    if (!solidRenderer) {
        throw new Error("Solid renderer is not created. Make sure setUp is called first");
    }

    const name = stringInterner.getStringByInternedRef(anchorNode.n);
    if (!name) {
        throw new Error("Failed to get name");
    }
    const constructComponent = tsComponentConstructors.get(name);
    if (!constructComponent) {
        throw new Error("Failed to get constructor");
    }
    return constructComponent(anchorNode);
}

export function updateInputs(anchorNode: AnchorNode, inputFieldName: InternedStringRef, value: PropValue) {
    ;

    const updateInputs = tsComponentUpdateInputs.get(anchorNode.r);
    if (!updateInputs) {
        throw new Error("Failed to get update props");
    }

    updateInputs(inputFieldName, value);
}

export function updateOutputs(
    anchorNode: AnchorNode,
    outputFieldName: InternedStringRef,
    outputHandler: OutputHandler
) {
    ;
    const updateOutputs = tsComponentUpdateOutputs.get(anchorNode.r);
    if (!updateOutputs) {
        throw new Error("Failed to get update outputs");
    }

    updateOutputs(outputFieldName, outputHandler);
}

let solidRenderer: SolidRenderer;
let anchorNodeManipulationApi: AnchorManipulationApi;

export function setUp({
    declareApi: incomingDeclareApi,
    tmApi: incomingTmApi,
    anchorNodeApi,
    internStringApi,
    transactionApi,
    incomingSDApi,
    outgoingSDApi
}: {
    declareApi: ComponentDeclaration;
    tmApi: TreeManipulationApi;
    anchorNodeApi: AnchorManipulationEventApi;
    internStringApi: InternStringApi;
    transactionApi: TransactionApi;
    incomingSDApi: StructuredDataApi;
    outgoingSDApi: StructuredDataApi;
}) {
    ;

    registerInternStringApi(internStringApi);
    declareApi = incomingDeclareApi;
    registerTransactionApi(transactionApi);
    solidRenderer = makeSolidRenderer(incomingTmApi, incomingSDApi, outgoingSDApi);
    anchorNodeManipulationApi = makeAnchorNodeManager(incomingSDApi, outgoingSDApi, anchorNodeApi);

    roku.Setup.initApiObject({
        anchorNode: anchorNodeManipulationApi,
        structuredData: incomingSDApi,
        treeManipulation: solidRenderer.tmFieldChangeHandlerApi
    });

    ;
}
