import { logger } from "@roku-sdk/common";
import { AppInfo, type DoneCallback } from "@roku-sdk/interfaces";

/**
 * Reads the universal source map SHA from the embedded app manifest.
 *
 * The SHA is stored under the `source_map_sha` key in the manifest and is used to
 * correlate raw production stack traces with the correct universal source map for
 * symbolication.
 *
 * @returns The source map SHA string, or `"<none>"` if unavailable.
 */
function getManifestSourceMapSHA(): string {
    try {
        // Cast required: the internal global.d.ts overloads getRuntimeSingletonSync with a
        // different enum type; passing the string value directly avoids the type conflict.
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const appInfo = roku.getRuntimeSingletonSync<AppInfo>("AppInfo" as any);
        if (!appInfo) {
            return "<none>";
        }
        const sha = appInfo.getManifestValue("hbc_source_map_sha");
        return sha || "<none>";
    } catch {
        return "<none>";
    }
}

/**
 * Builds the multi-bundle [SourceMap: ...] tag string.
 *
 * Format: `index:{hostSha}[ {lib}:{dclSha}]*`
 * The `index` key matches the host HBC filename; each DCL entry uses its library name
 * (which also matches the renamed DCL HBC filename, e.g. `tsDCL.hbc`).
 */
function buildSourceMapTag(): string {
    const hostSha = getManifestSourceMapSHA();
    const parts: string[] = [`index:${hostSha}`];

    const dclShas = globalThis.__DCL_SOURCE_MAP_SHAS;
    if (dclShas) {
        for (const lib in dclShas) {
            parts.push(`${lib}:${dclShas[lib]}`);
        }
    }

    return parts.join(" ");
}

/** Logs the error and source_map_sha (host + all loaded DCLs). Returns the host SHA. */
function logExceptionWithSHA(error: Error | null | undefined): string {
    logger.error(() => (error ? error.toString() : "Uncaught exception"));
    const sha = getManifestSourceMapSHA();
    logger.error(() => `source_map_sha=${sha}`);
    // Also log each loaded DCL's SHA so log scrapers can correlate DCL frames.
    const dclShas = globalThis.__DCL_SOURCE_MAP_SHAS;
    if (dclShas) {
        for (const lib in dclShas) {
            logger.error(() => `source_map_sha=${lib}:${dclShas![lib]}`);
        }
    }
    return sha;
}

/** Subset of the V8 CallSite API used for stack frame formatting. */
interface CallSite {
    getFunctionName(): string | null;
    getFileName(): string | null;
    getLineNumber(): number | null;
    getColumnNumber(): number | null;
    isConstructor(): boolean;
}

function formatCallSite(frame: CallSite): string {
    const fn = frame.getFunctionName();
    const file = frame.getFileName() ?? "<anonymous>";
    const line = frame.getLineNumber() ?? 0;
    const col = frame.getColumnNumber() ?? 0;
    const loc = `${file}:${line}:${col}`;
    if (frame.isConstructor()) {
        return `    at new ${fn ?? "<anonymous>"} (${loc})`;
    }
    return fn ? `    at ${fn} (${loc})` : `    at ${loc}`;
}

type StackTraceFormatter = (error: Error, stack: CallSite[]) => string;

let exceptionTaggingEnabled = false;

/**
 * Registers an `Error.prepareStackTrace` hook (or fallback `Error.prototype.stack`
 * getter override) that appends a `[SourceMap: <sha>]` tag to every `Error.stack`
 * string.  The SHA is read from the `hbc_source_map_sha` field in the application
 * manifest, enabling later symbolication via `rk decode-stack`.
 *
 * Safe to call multiple times — only the first invocation has any effect.
 *
 * @example
 * ```ts
 * import { main, enableExceptionTagging } from "@roku-sdk/rsg-ts";
 * main(() => {
 *     enableExceptionTagging();
 *     registerAnchorNode(MyComponent);
 * });
 * ```
 */
export function enableExceptionTagging(): void {
    if (exceptionTaggingEnabled) return;
    exceptionTaggingEnabled = true;

    // Error.prepareStackTrace is a V8 / Hermes extension.  We cast through
    // `unknown` to assign a custom signature without conflicting with
    // @types/node's declaration.
    let useCustomFormatter = false;
    try {
        const testError = new Error();
        const testStack: CallSite[] = [];
        const originalPrepare = (Error as unknown as { prepareStackTrace?: StackTraceFormatter }).prepareStackTrace;
        (Error as unknown as { prepareStackTrace?: StackTraceFormatter }).prepareStackTrace = (
            _e: Error,
            stack: CallSite[]
        ) => {
            testStack.push(...stack);
            return "";
        };
        const errorWithCapture = Error as unknown as { captureStackTrace?: (targetObject: object) => void };
        errorWithCapture.captureStackTrace?.(testError);
        void testError.stack;
        (Error as unknown as { prepareStackTrace?: StackTraceFormatter }).prepareStackTrace = originalPrepare;

        const firstFrame = testStack[0];
        useCustomFormatter = firstFrame !== undefined && firstFrame.getColumnNumber() !== null;
    } catch {
        useCustomFormatter = false;
    }

    if (useCustomFormatter) {
        (Error as unknown as { prepareStackTrace?: StackTraceFormatter }).prepareStackTrace = (
            error: Error,
            stack: CallSite[]
        ) => {
            const newline = String.fromCharCode(10);
            const rawStackTrace = stack.map(frame => formatCallSite(frame)).join(newline);
            const tag = buildSourceMapTag();
            return [error.toString(), newline, rawStackTrace, newline, "    [SourceMap: ", tag, "]", newline].join("");
        };
    } else {
        const originalStackGetter = Object.getOwnPropertyDescriptor(Error.prototype, "stack")?.get;
        if (originalStackGetter) {
            Object.defineProperty(Error.prototype, "stack", {
                get: function (this: Error) {
                    const nativeStack = originalStackGetter.call(this);
                    if (typeof nativeStack === "string" && !nativeStack.includes("[SourceMap:")) {
                        const tag = buildSourceMapTag();
                        return [nativeStack, "\n    [SourceMap: ", tag, "]\n"].join("");
                    }
                    return nativeStack;
                },
                configurable: true
            });
        }
    }
}

const MIN_TIMEOUT_MS = 100;

type CustomExceptionHandler = (error: Error, sha: string, done: DoneCallback) => void;
let customExceptionHandler: CustomExceptionHandler | null = null;

/**
 * Registers a developer-provided async handler that runs when an uncaught
 * exception occurs, giving the application a window to forward the error to
 * an external monitoring service before the process exits (or resumes, when
 * `options.resume` is true).
 *
 * The SDK's default logging (error message + `source_map_sha`) is preserved
 * automatically.  The handler's Promise is awaited up to `options.timeout`
 * milliseconds (default 5 000, minimum 100); once the Promise settles or the
 * timeout expires (whichever comes first), the runtime is notified via `done`:
 * - default / `resume: false` → `done(true)` (exit the plugin)
 * - `resume: true` → `done(false)` (resume the event loop without exiting)
 *
 * Handler errors and timeouts still invoke `done` with the same exit/resume
 * flag chosen via `options.resume`.
 *
 * Calling this function replaces any previously registered handler (including
 * the SDK default).  Only the last registered handler is active.  There is no
 * way to restore the SDK default after calling this function.
 *
 * This API only covers uncaught exceptions (setUncaughtExceptionCaptureCallback).
 * Unhandled Promise rejections remain handled by the SDK's default
 * setUnhandledRejectionCallback logger and are not forwarded to this handler.
 *
 * If the runtime passes a falsy error (e.g., null), the handler receives a
 * synthesized Error object with message "Uncaught exception (no error object
 * provided)" so that error.message / error.stack access is always safe.
 */
export function setUncaughtExceptionHandler(
    handler: (error: Error) => Promise<void>,
    options: { timeout?: number; resume?: boolean } = {}
): void {
    const timeoutMs = Math.max(options.timeout ?? 5000, MIN_TIMEOUT_MS);
    // done(false) = resume; done(true) / done() = exit.
    const exit = options.resume !== true;

    if (typeof globalThis.Process === "undefined") {
        logger.warn(() => "setUncaughtExceptionHandler: globalThis.Process is not available");
        return;
    }

    customExceptionHandler = (error: Error, sha: string, done: DoneCallback) => {
        const safeError = error ?? new Error("Uncaught exception (no error object provided)");

        if (
            exceptionTaggingEnabled &&
            typeof safeError.stack === "string" &&
            !safeError.stack.includes("[SourceMap:")
        ) {
            const tag = buildSourceMapTag();
            safeError.stack = [safeError.stack, "\n    [SourceMap: ", tag, "]"].join("");
        }

        let settled = false;
        const finish = () => {
            if (settled) return;
            settled = true;
            clearTimeout(timeoutHandle);
            try {
                done(exit);
            } catch (doneError) {
                console.error("done() threw:", doneError);
            }
        };

        const timeoutHandle = setTimeout(() => {
            console.warn(`Exception handler timed out after ${timeoutMs}ms`);
            finish();
        }, timeoutMs);

        Promise.resolve()
            .then(() => handler(safeError))
            .then(() => finish())
            .catch(handlerError => {
                console.error("Exception handler failed:", handlerError);
                finish();
            });
    };
}

/**
 * Registers uncaught exception and unhandled rejection handlers on the supplied
 * process-like API object.
 *
 * The module calls this at load time with `globalThis.Process`. It is not exported from the
 * package entry point; unit tests import it from source.
 */
export function setupProcessHandlers(processApi: {
    setUncaughtExceptionCaptureCallback: (cb: (error: Error, done: DoneCallback) => void) => void;
    setUnhandledRejectionCallback: (cb: (id: unknown, error: Error) => void) => void;
}): void {
    processApi.setUncaughtExceptionCaptureCallback((error: Error, done: DoneCallback) => {
        const sha = logExceptionWithSHA(error);
        if (customExceptionHandler) {
            customExceptionHandler(error, sha, done);
        } else {
            done(true);
        }
    });

    processApi.setUnhandledRejectionCallback((id, error: Error) => {
        logger.error(() => (error ? error.toString() : `Unhandled rejection with id: ${id}`));
    });
}

/** Clears the handler set by `setUncaughtExceptionHandler`. Not exported from the package; unit tests import it from source. */
export function _resetCustomExceptionHandler(): void {
    customExceptionHandler = null;
}

// Set up global error handlers at module load time.
// TODO: change to object name to process
if (typeof globalThis.Process !== "undefined") {
    setupProcessHandlers(globalThis.Process);
}
