declare const __DEV__: boolean;
import { installConsolePolyfill } from "./console-polyfill";

if (__DEV__) {
    installConsolePolyfill();
}

// Re-exported so production builds that intentionally keep `console.*`
// calls (`dropConsole: false`) can opt back into the polyfill even
// though the `__DEV__`-gated auto-install above is tree-shaken out.
// The on-device polyfill verifier (`apps/native/console-polyfills`) relies on
// this to exercise the real implementation in a non-dev build.
export { installConsolePolyfill } from "./console-polyfill";
import "./fetch-polyfill";
// Side-effect import: registers the default uncaught-exception and
// unhandled-rejection handlers at module load time via setupProcessHandlers().
// Do NOT remove -- the re-export below does not guarantee side effects run.
import "./process";

export { enableExceptionTagging, setUncaughtExceptionHandler } from "./process";
export { FinalizationRegistry } from "./finalization-registry-ponyfill";

import { logger } from "@roku-sdk/common";
import { makeStructuredDataHandler, setUp } from "@roku-sdk/ts-core";

let runtimeSetUp = false;

/**
 * Sets up the TypeScript runtime, then runs `declare` and commits the components it declared.
 *
 * Set-up happens once per copy of the SDK. A later call on the same copy skips it and only
 * declares and commits.
 */
export function main(declare: () => void): void {
    if (runtimeSetUp) {
        ;
    } else {
        runtimeSetUp = true;
        setUpRuntime();
    }
    declare();
    roku.ComponentDeclarationApi.commit();
}

function setUpRuntime(): void {
    logger.info(() => "main begins");
    const internStringApi = roku.InternStringApi;
    const tmApi = roku.TreeManipulationApi;
    const anchorNodeApi = roku.AnchorManipulationEventApi;
    const declareApi = roku.ComponentDeclarationApi;
    const transactionApi = roku.Transaction;
    // Install before app declaration; an app's setErrorCallback replaces this single native handler.
    if (typeof transactionApi.setErrorCallback === "function") {
        const txLogger = logger.getLogger("tx");
        transactionApi.setErrorCallback((errorRef, count) => {
            for (let index = 0; index < count; index++) {
                txLogger.error(() => {
                    const reason = transactionApi.getErrorReason?.(errorRef, index);
                    const reasonName =
                        Object.keys(roku.TmErrorReason ?? {}).find(name => roku.TmErrorReason?.[name] === reason) ??
                        reason;
                    const details = [
                        ["operation", transactionApi.getErrorOperation?.(errorRef, index)],
                        ["nodeId", transactionApi.getErrorNodeId?.(errorRef, index)],
                        ["propName", transactionApi.getErrorPropName?.(errorRef, index)]
                    ]
                        .filter(([, value]) => value !== undefined)
                        .map(([key, value]) => `${key}=${value}`);
                    return `Transaction error ${reasonName}: ${transactionApi.getErrorMessage?.(errorRef, index) ?? ""}${details.length ? ` (${details.join(", ")})` : ""}`;
                });
            }
        });
    }
    const incomingSDApi = makeStructuredDataHandler();
    const outgoingSDApi = roku.StructuredDataApi;

    setUp({
        declareApi,
        tmApi,
        anchorNodeApi,
        internStringApi,
        transactionApi,
        incomingSDApi,
        outgoingSDApi
    });
}
