import { Logger, LoggerAPI, LoggerRef } from "@roku-sdk/interfaces";
import { RuntimeInterfaces } from "@roku-sdk/interfaces";

import { getBuildVariable } from "./build-variables";

declare const __BASE_LOG_LEVEL__: string;
declare const __CURRENT_LOG_LEVEL__: string;

/**
 * Logger interface with internal loggerRef property
 */
interface LoggerWithRef extends Logger {
    __loggerRef: LoggerRef;
}

/**
 * This module provides a logger implementation that routes logs to the
 * runtime logger API. It supports different log levels and allows for
 * filtering logs based on the source.
 */

// Both symbols are registered on `roku` before this module is evaluated, so it is
// safe to destructure them at module load.
const { getRuntimeSingletonSync, LogLevel } = roku;

const loggerAPI: LoggerAPI = getRuntimeSingletonSync<LoggerAPI>(RuntimeInterfaces.LoggerAPI) as LoggerAPI;

const baseLogLevelStr = getBuildVariable(__BASE_LOG_LEVEL__, "INFO");
const currentLogLevelStr = getBuildVariable(__CURRENT_LOG_LEVEL__, "ERROR");

const baseLevel: number = LogLevel[baseLogLevelStr.toUpperCase()] ?? LogLevel.INFO;
const currentLevel: number = LogLevel[currentLogLevelStr.toUpperCase()] ?? LogLevel.ERROR;
// TODO: Implement log level update handler
// loggerAPI.setCurrentLogLevelUpdateHandler((logLevel: LogLevel): void => {
//     currentLevel = logLevel;
// });

const logSourceFilter: string | null = null;
// TODO: Implement log source filter update handler
// loggerAPI.setLogSourceFilterUpdateHandler((filter: string): void => {
//     logSourceFilter = filter;
// });

function createLogger(source: string = ""): LoggerWithRef {
    const loggerRef = loggerAPI.getLoggerRef(source);
    const logHandlers: Array<(source: string, level: number, message: string) => void> = [];
    function logByLevel(
        loggerRef: LoggerRef,
        level: number,
        messageProvider: () => string,
        logSourceSuffix?: string
    ): void {
        // TODO: fix logSourceSuffix regex. Check the performance impact when using regex.
        if (
            baseLevel <= level &&
            currentLevel <= level &&
            (logSourceFilter === null || source.startsWith(logSourceFilter))
        ) {
            const message = messageProvider();
            loggerAPI.logDevConsole(loggerRef, level, message, logSourceSuffix);
            for (const handler of logHandlers) {
                handler(source, level, message);
            }
        }
    }
    const logger: LoggerWithRef = {
        trace: (messageProvider: () => string, logSourceSuffix?: string): void => {
            logByLevel(loggerRef, LogLevel.TRACE, messageProvider, logSourceSuffix);
        },
        debug: (messageProvider: () => string, logSourceSuffix?: string): void => {
            logByLevel(loggerRef, LogLevel.DEBUG, messageProvider, logSourceSuffix);
        },
        info: (messageProvider: () => string, logSourceSuffix?: string): void => {
            logByLevel(loggerRef, LogLevel.INFO, messageProvider, logSourceSuffix);
        },
        warn: (messageProvider: () => string, logSourceSuffix?: string): void => {
            logByLevel(loggerRef, LogLevel.WARN, messageProvider, logSourceSuffix);
        },
        error: (messageProvider: () => string, logSourceSuffix?: string): void => {
            logByLevel(loggerRef, LogLevel.ERROR, messageProvider, logSourceSuffix);
        },
        getLogger: (childSource: string): Logger => {
            return createLogger(source ? `${source}.${childSource}` : childSource);
        },
        // Log handler registration methods
        registerLogHandler: (handler: (source: string, level: number, message: string) => void): void => {
            logHandlers.push(handler);
        },
        unregisterLogHandler: (handler: (source: string, level: number, message: string) => void): void => {
            const index = logHandlers.indexOf(handler);
            if (index !== -1) {
                logHandlers.splice(index, 1);
            }
        },
        __loggerRef: loggerRef
    };

    ;
    return logger;
}
export const logger = createLogger();
