const featureSupport = new Map<string, boolean>();

/**
 * Reports whether the firmware supports a feature, caching each answer for the app's lifetime.
 *
 * Returns false for unknown keys and when `roku.hasFeature` is unavailable, including
 * older firmware and non-device environments. Feature strings are added in firmware source.
 *
 * @param key - The firmware-defined feature string to query.
 * @returns Whether the firmware reports support for the feature.
 */
export function hasFeature(key: string): boolean {
    const cached = featureSupport.get(key);
    if (cached !== undefined) return cached;

    const supported =
        typeof roku !== "undefined" && typeof roku?.hasFeature === "function" ? roku.hasFeature(key) : false;
    featureSupport.set(key, supported);
    return supported;
}
