import { DomNode, domNodeSymbol, TmNodeRef, TmValue } from "@roku-sdk/interfaces";

type SetPropertyHandler = (node: DomNode, name: string, value: TmValue) => void;

const defaultProto = { _s: domNodeSymbol };
const tagProtoMap = new Map<string, object>();
const imperativeMethodsRegistry = new Map<string, PropertyDescriptorMap>();
let focusHandler: ((focusNode: DomNode) => void) | undefined;
let blurHandler: ((blurNode: DomNode) => void) | undefined;
let setPropertyHandler: SetPropertyHandler | undefined;

function setPropertyValue(node: DomNode, name: string, value: TmValue) {
    setPropertyHandler?.(node, name, value);
}

/**
 * Creates a data PropertyDescriptor for an imperative method that sets a property on the node.
 * The returned descriptor is always a non-writable, non-enumerable, non-configurable data descriptor.
 *
 * @param propName - The property name to set on the underlying SceneGraph node.
 * @param fixedValue - If provided, the method takes no arguments and always sets this value.
 *                     If omitted, the method takes one argument and sets it as the value.
 * @returns A data PropertyDescriptor whose `value` is the imperative method function.
 *
 * @example
 * // Zero-arg method: sets control = "play"
 * setPropMethod("control", "play")
 *
 * // One-arg method: sets seek = <user-provided value>
 * setPropMethod("seek")
 */
export function setPropMethod(propName: string, fixedValue?: TmValue): PropertyDescriptor {
    if (fixedValue !== undefined) {
        return {
            value: function (this: DomNode) {
                setPropertyValue(this, propName, fixedValue);
            },
            writable: false,
            enumerable: false,
            configurable: false
        };
    }
    return {
        value: function (this: DomNode, value: TmValue) {
            setPropertyValue(this, propName, value);
        },
        writable: false,
        enumerable: false,
        configurable: false
    };
}

/**
 * Registers imperative methods for a given tag. Methods are attached to the node prototype
 * when the first node of that tag is created.
 *
 * Must be called before any node of the given tag is created (i.e., at module load time
 * in the component file that defines the tag). Late registration has no effect on
 * already-created prototypes because `getOrCreatePrototype` caches in `tagProtoMap`.
 */
export function registerImperativeMethods(tag: string, methods: PropertyDescriptorMap): void {
    if (imperativeMethodsRegistry.has(tag)) {
        console.warn(`[solid] Duplicate imperative methods registration for tag "${tag}"`);
    }
    if (tagProtoMap.has(tag)) {
        console.warn(
            `[solid] Late imperative methods registration for tag "${tag}": nodes already created with this tag will not receive the new methods`
        );
    }
    imperativeMethodsRegistry.set(tag, methods);
}

function addImperativeMethods(tag: string, proto: object): void {
    const methods = imperativeMethodsRegistry.get(tag);
    if (methods) {
        Object.defineProperties(proto, methods);
    }
}

export function createDomNode(tag: string, nodeRef: TmNodeRef): DomNode {
    if (!tagProtoMap.has(tag)) {
        const objByTag = Object.create(defaultProto, {
            t: {
                // Not storing interned string ref since this object is never sent to other domain.
                // Hermes does intern all string literals.
                // Do use tagRef if we use js engine that does not support string interning.
                value: tag,
                writable: false,
                enumerable: true,
                configurable: false
            },
            focus: {
                value: function () {
                    focusHandler?.(this);
                },
                writable: false,
                enumerable: false,
                configurable: false
            },
            blur: {
                value: function () {
                    blurHandler?.(this);
                },
                writable: false,
                enumerable: false,
                configurable: false
            }
        });

        addImperativeMethods(tag, objByTag);

        tagProtoMap.set(tag, objByTag);
    }

    const node: DomNode = Object.create(tagProtoMap.get(tag)!, {
        r: {
            value: nodeRef,
            writable: false,
            enumerable: true,
            configurable: false
        },
        parent: {
            value: undefined,
            writable: true,
            enumerable: false,
            configurable: false
        }
    });

    return node;
}

export function isDomNode(node: DomNode): node is DomNode {
    return node?._s === domNodeSymbol;
}

export function setFocusHandler(handler: (focusNode: DomNode) => void): void {
    focusHandler = handler;
}

export function setBlurHandler(handler: (blurNode: DomNode) => void): void {
    blurHandler = handler;
}

export function setSetPropertyHandler(handler: SetPropertyHandler): void {
    setPropertyHandler = handler;
}
