/**
 * Backward-compatibility shim for the global `roku` namespace.
 *
 * Framework code references Roku runtime objects (e.g. `InternStringApi`,
 * `getRuntimeSingletonSync`, `perfetto`, `Setup`, `MemoryLevel`, `crypto`) as
 * members of a single global `roku` object. Older firmware does not install that
 * namespace and instead exposes those objects as bare globals, so a direct
 * `roku.<member>` access would throw `ReferenceError` there.
 *
 * `installRokuCompat()` installs a `globalThis.roku` Proxy that resolves each
 * member from the firmware-provided namespace when present and otherwise falls
 * back, per member, to the legacy bare global. Framework code keeps using the
 * ambient `roku` global unchanged.
 *
 * TODO: remove this entire module once the minimum supported firmware always
 * provides the `roku` namespace. Then drop the side-effect imports in the
 * external and internal `interfaces/src/index.ts` barrels.
 */

const COMPAT_MARKER = "__rsgCompat";

interface CompatMarked {
    [COMPAT_MARKER]?: boolean;
}

/**
 * Installs the per-member fallback Proxy on `globalThis.roku`. Idempotent: a
 * second call is a no-op once the compat Proxy is in place.
 */
export function installRokuCompat(): void {
    const g = globalThis as unknown as Record<string, unknown>;
    const real = g.roku as (Record<string, unknown> & CompatMarked) | undefined;

    // Already wrapped by a previous call — nothing to do.
    if (real && real[COMPAT_MARKER]) {
        return;
    }

    const hasOwn = (obj: object, prop: string | symbol): boolean => Object.prototype.hasOwnProperty.call(obj, prop);

    const compat = new Proxy({} as RokuNamespace, {
        // Resolution order: local writes/overrides on the proxy → firmware-provided
        // `roku` member → legacy bare global (firmware without the `roku` namespace).
        get(target, prop: string | symbol): unknown {
            if (prop === COMPAT_MARKER) {
                return true;
            }
            if (hasOwn(target, prop)) {
                return (target as unknown as Record<string | symbol, unknown>)[prop];
            }
            if (real && (real as Record<string | symbol, unknown>)[prop] !== undefined) {
                return (real as Record<string | symbol, unknown>)[prop];
            }
            return (g as Record<string | symbol, unknown>)[prop];
        },
        has(target, prop: string | symbol): boolean {
            if (prop === COMPAT_MARKER) {
                return true;
            }
            return hasOwn(target, prop) || (!!real && prop in real) || prop in g;
        }
    });

    g.roku = compat;
}

installRokuCompat();
