import { StructuredDataApi, TmArrayRef, TmObjectRef } from "@roku-sdk/interfaces";

import { logger } from "./logger";

const sdLogger = logger.getLogger("sd");

export const createSDHelper = (api: StructuredDataApi) => {
    const createFullObject = (props: object, tracked = new WeakSet<object>()): TmObjectRef => {
        // Check for circular references
        if (tracked.has(props)) {
            sdLogger.error(() => "Circular reference detected in object");
            throw new Error("Circular reference detected in object");
        }
        tracked.add(props);

        const objRef = api.createObject() as object;
        Object.entries(props).forEach(([prop, value]) => {
            switch (typeof value) {
                case "number":
                    if (Number.isInteger(value)) {
                        api.insertInt(objRef, prop, value);
                    } else {
                        api.insertFloat(objRef, prop, value);
                    }
                    break;
                case "boolean":
                    api.insertBool(objRef, prop, value);
                    break;
                case "string":
                    api.insertString(objRef, prop, value);
                    break;
                case "object":
                    if (value === null) {
                        api.insertNull(objRef, prop);
                    } else if (Array.isArray(value)) {
                        const arrayRef = createFullArray(value, tracked);
                        api.insertArray(objRef, prop, arrayRef);
                    } else {
                        const objectRef: TmObjectRef = createFullObject(value, tracked);
                        api.insertObject(objRef, prop, objectRef);
                    }
                    break;
            }
        });
        return objRef;
    };

    const createFullArray = (array: unknown[], tracked = new WeakSet<object>()): TmArrayRef => {
        ;
        if (tracked.has(array)) {
            sdLogger.error(() => "Circular reference detected in array");
            throw new Error("Circular reference detected in array");
        }
        tracked.add(array);

        const arrayRef = api.createArray() as object;
        array.forEach(value => {
            switch (typeof value) {
                case "boolean":
                    api.appendBool(arrayRef, value);
                    break;
                case "number":
                    if (Number.isInteger(value)) {
                        api.appendInt(arrayRef, value);
                    } else {
                        api.appendFloat(arrayRef, value);
                    }
                    break;
                case "string":
                    api.appendString(arrayRef, value);
                    break;
                case "object":
                    if (value === null) {
                        api.appendNull(arrayRef);
                    } else if (Array.isArray(value)) {
                        const nestedArrayRef = createFullArray(value, tracked);
                        api.appendArray(arrayRef, nestedArrayRef);
                    } else {
                        const objectRef: TmObjectRef = createFullObject(value, tracked);
                        api.appendObject(arrayRef, objectRef);
                    }
                    break;
            }
        });
        return arrayRef;
    };

    const commit = () => {
        // No-op: circular reference tracking is scoped per-call via the tracked parameter.
    };

    return {
        createFullObject,
        createFullArray,
        commit
    };
};
