import { StructuredDataApi, TmArrayRef, TmNodeRef, TmObjectRef, TmStringRef, TmValue } from "@roku-sdk/interfaces";

type IncomingObject = { [key: string]: IncomingValue };
type IncomingValue = TmValue | IncomingValue[] | IncomingObject | null;

const incomingArrays = new Map<TmArrayRef | number, IncomingValue[]>();
const incomingObjects = new Map<TmObjectRef | number, IncomingObject>();
let refValue = 0;

export function makeStructuredDataHandler(): StructuredDataApi {
    const appendValue = (arrayRef: TmArrayRef, value: IncomingValue): void => {
        const array = incomingArrays.get(arrayRef);
        if (array) {
            array.push(value);
        }
    };
    const insertValue = (objectRef: TmArrayRef, propName: string | TmStringRef, value: IncomingValue): void => {
        const array = incomingObjects.get(objectRef);
        if (array) {
            array[propName as string] = value;
        }
    };
    const notImplemented = () => {
        throw new Error("Not implemented");
    };
    return {
        createArray: () => {
            ++refValue;
            incomingArrays.set(refValue, []);
            return refValue;
        },
        appendArray(arrayRef: TmArrayRef, value: TmArrayRef): void {
            const valueArray = incomingArrays.get(value) as IncomingValue[];
            appendValue(arrayRef, valueArray);
        },
        appendBool: (arrayRef: TmArrayRef, value: boolean): void => appendValue(arrayRef, value),
        appendFloat: (arrayRef: TmArrayRef, value: number): void => appendValue(arrayRef, value),
        appendInt: (arrayRef: TmArrayRef, value: number): void => appendValue(arrayRef, value),
        appendNodeRef: (arrayRef: TmArrayRef, value: TmNodeRef): void => appendValue(arrayRef, value),
        appendNull: (arrayRef: TmArrayRef): void => appendValue(arrayRef, null),
        appendObject(arrayRef: TmArrayRef, value: TmObjectRef): void {
            const valueObject = incomingObjects.get(value);
            if (!valueObject) {
                throw new Error(`Object ${value} not found`);
            }
            appendValue(arrayRef, valueObject);
        },
        appendString: (arrayRef: TmArrayRef, value: string | TmStringRef): void => appendValue(arrayRef, value),

        createObject(): TmObjectRef | number {
            ++refValue;
            incomingObjects.set(refValue, {});
            return refValue;
        },
        insertArray(objectRef: TmObjectRef, propName: string | TmStringRef, value: TmArrayRef): void {
            const valueArray = incomingArrays.get(value) as IncomingValue[];
            insertValue(objectRef, propName, valueArray);
        },
        insertBool: (objectRef: TmObjectRef, propName: string | TmStringRef, value: boolean): void =>
            insertValue(objectRef, propName, value),
        insertFloat: (objectRef: TmObjectRef, propName: string | TmStringRef, value: number): void =>
            insertValue(objectRef, propName, value),
        insertInt: (objectRef: TmObjectRef, propName: string | TmStringRef, value: number): void =>
            insertValue(objectRef, propName, value),
        insertNodeRef(
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            objectRef: TmObjectRef,
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            propName: string | TmStringRef,
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            value: TmNodeRef
        ): void {
            notImplemented();
        },
        insertNull: (objectRef: TmObjectRef, propName: string | TmStringRef): void =>
            insertValue(objectRef, propName, null),
        insertObject(objectRef: TmObjectRef, propName: string | TmStringRef, value: TmObjectRef): void {
            const valueObject = incomingObjects.get(value);
            if (!valueObject) {
                throw new Error(`Object ${value} not found`);
            }
            insertValue(objectRef, propName, valueObject);
        },
        insertString: (objectRef: TmObjectRef, propName: string | TmStringRef, value: string): void =>
            insertValue(objectRef, propName, value),
        getArray: (arrayRef: TmArrayRef | number): IncomingValue[] | undefined => {
            const arr = incomingArrays.get(arrayRef);
            incomingArrays.delete(arrayRef);
            return arr;
        },
        getObject: (objectRef: TmObjectRef | number): IncomingObject | undefined => {
            const obj = incomingObjects.get(objectRef);
            incomingObjects.delete(objectRef);
            return obj;
        }
    };
}
