import {
    HeadersInit,
    HeadersInstance,
    HttpsAgentInstance,
    HttpsAgentOptions,
    RequestInit,
    RequestInstance
} from "@roku-sdk/interfaces";

function Request(url: string, init?: RequestInit): RequestInstance {
    return globalThis.RequestHostFunc.call(null, url, init);
}

function HttpsAgent(options?: HttpsAgentOptions): HttpsAgentInstance {
    return globalThis.HttpsAgentHostFunc.call(null, options);
}

function Headers(init?: HeadersInit): HeadersInstance {
    return globalThis.HeadersHostFunc.call(null, init);
}

// Cast through unknown to avoid type conflicts with DOM types
globalThis.Request = Request as unknown as typeof globalThis.Request;
globalThis.HttpsAgent = HttpsAgent as unknown as typeof globalThis.HttpsAgent;
globalThis.Headers = Headers as unknown as typeof globalThis.Headers;
