import { logger } from "@roku-sdk/common";
import { createSDHelper } from "@roku-sdk/common/sd-helper";
import { stringInterner } from "@roku-sdk/common/string-interner";
import { transactionManager } from "@roku-sdk/common/transaction";
import {
    AnchorManipulationEventApi,
    AnchorNode,
    AnNodeRef,
    InternedStringRef,
    OutputHandler,
    PropValue,
    StructuredDataApi
} from "@roku-sdk/interfaces";
import { forgetAnchor } from "@roku-sdk/solid";

import { canComponentReceiveFocus, constructor, updateInputs, updateOutputs } from "./bootstrap";

type Destructor = () => void;

export function makeAnchorNodeManager(
    incomingSDApi: StructuredDataApi,
    outgoingSDApi: StructuredDataApi,
    anchorNodeApi: AnchorManipulationEventApi
) {
    // NOTE: create new SDHelper for outgoing data.
    // In a transaction there can be two outgoing SDHelpers, one for outgoing anchor node data and other for outgoing tm data.
    // So same outgoing data can be passed from anchor node and thru tm node.
    const { createFullArray, createFullObject, commit: sdCommit } = createSDHelper(outgoingSDApi);
    const anchorNodes = new Map<AnNodeRef, AnchorNode>();
    const anchorNodeDestructors = new Map<AnNodeRef, Destructor>();

    function getAnchorNode(nodeRef: AnNodeRef): AnchorNode {
        const anchorNode = anchorNodes.get(nodeRef);
        if (!anchorNode) {
            throw new Error(`Anchor node not found for ref: ${JSON.stringify(nodeRef)}`);
        }
        return anchorNode;
    }

    function setAnchorNodeProp(nodeRef: AnNodeRef, fieldName: InternedStringRef, value: unknown) {
        updateInputs(getAnchorNode(nodeRef), fieldName, value as PropValue);
    }

    const handleOutputFields = (
        nodeRef: AnNodeRef,
        fieldName: InternedStringRef,
        eventData: Parameters<OutputHandler>[0]
    ) => {
        const eventDataType = typeof eventData;
        transactionManager.startTransaction();
        switch (eventDataType) {
            case "boolean":
                anchorNodeApi.onAnchorNodeBoolPropChange(nodeRef, fieldName, eventData as boolean);
                break;
            case "number":
                if (Number.isInteger(eventData)) {
                    anchorNodeApi.onAnchorNodeIntPropChange(nodeRef, fieldName, eventData as number);
                } else {
                    anchorNodeApi.onAnchorNodeFloatPropChange(nodeRef, fieldName, eventData as number);
                }
                break;
            case "string":
                anchorNodeApi.onAnchorNodeStringPropChange(nodeRef, fieldName, eventData as string);
                break;
            case "object":
                if (eventData === null) {
                    anchorNodeApi.onAnchorNodeNullPropChange(nodeRef, fieldName);
                } else if (Array.isArray(eventData)) {
                    const arrayRef = createFullArray(eventData);
                    anchorNodeApi.onAnchorNodeArrayPropChange(nodeRef, fieldName, arrayRef);
                } else {
                    const objectRef = createFullObject(eventData as object);
                    anchorNodeApi.onAnchorNodeObjectPropChange(nodeRef, fieldName, objectRef);
                }
                break;
            default:
                logger.error(() => `Unknown event data type ${eventDataType}`);
        }
        sdCommit();
    };

    return {
        createAnchorNode: (componentName: InternedStringRef, nodeRef: AnNodeRef) => {
            const name = stringInterner.getStringByInternedRef(componentName);
            const anchorNode: AnchorNode = {
                r: nodeRef,
                n: componentName,
                canReceiveFocus: name ? canComponentReceiveFocus(name) : false
            };
            anchorNodes.set(anchorNode.r, anchorNode);
            const destructor = constructor(anchorNode);
            anchorNodeDestructors.set(anchorNode.r, destructor);
        },
        removeAnchorNode: (nodeRef: AnNodeRef) => {
            anchorNodeDestructors.get(nodeRef)?.();
            // After the destructor: cleanups that release focus run during dispose, and
            // forgetAnchor walks the anchor's tree, which is still attached at this point.
            const anchorNode = anchorNodes.get(nodeRef);
            if (anchorNode) forgetAnchor(anchorNode);
            anchorNodes.delete(nodeRef);
            anchorNodeDestructors.delete(nodeRef);
        },

        updateAnchorNodePropBool: (nodeRef: AnNodeRef, fieldName: InternedStringRef, value: boolean) => {
            setAnchorNodeProp(nodeRef, fieldName, value);
        },
        updateAnchorNodePropNull: (nodeRef: AnNodeRef, fieldName: InternedStringRef) => {
            setAnchorNodeProp(nodeRef, fieldName, null);
        },
        updateAnchorNodePropInt: (nodeRef: AnNodeRef, fieldName: InternedStringRef, value: number) => {
            setAnchorNodeProp(nodeRef, fieldName, value);
        },
        updateAnchorNodePropFloat: (nodeRef: AnNodeRef, fieldName: InternedStringRef, value: number) => {
            setAnchorNodeProp(nodeRef, fieldName, value);
        },
        updateAnchorNodePropString: (nodeRef: AnNodeRef, fieldName: InternedStringRef, value: string) => {
            setAnchorNodeProp(nodeRef, fieldName, value);
        },
        updateAnchorNodePropObject: (nodeRef: AnNodeRef, fieldName: InternedStringRef, ref: object) => {
            const anchorNode = getAnchorNode(nodeRef);
            const value = incomingSDApi.getObject(ref);
            updateInputs(anchorNode, fieldName, value as PropValue);
        },
        updateAnchorNodePropArray: (nodeRef: AnNodeRef, fieldName: InternedStringRef, ref: object) => {
            const anchorNode = getAnchorNode(nodeRef);
            const value = incomingSDApi.getArray(ref);
            updateInputs(anchorNode, fieldName, value as PropValue);
        },
        registerAnchorNodeEventListener: (nodeRef: AnNodeRef, outputFieldName: InternedStringRef) => {
            const anchorNode = getAnchorNode(nodeRef);
            const eventHandler: OutputHandler = eventData => {
                handleOutputFields(nodeRef, outputFieldName, eventData);
            };
            updateOutputs(anchorNode, outputFieldName, eventHandler);
        },
        unregisterAnchorNodeEventListener: (nodeRef: AnNodeRef, outputFieldName: InternedStringRef) => {
            const anchorNode = getAnchorNode(nodeRef);
            const eventHandler: OutputHandler = () => {};
            updateOutputs(anchorNode, outputFieldName, eventHandler);
        },
        removeAllAnchorNodes: () => {
            anchorNodes.forEach((anchorNode, nodeRef) => {
                anchorNodeDestructors.get(nodeRef)?.();
                forgetAnchor(anchorNode);
            });
            anchorNodes.clear();
            anchorNodeDestructors.clear();
        }
    };
}
