// Polyfills for Console API methods missing in Hermes.
// Indentation from group/groupCollapsed only applies to output generated by
// these polyfill functions — the global console.log is NOT wrapped.

const timers = new Map<string, number>();
const counters = new Map<string, number>();
let groupDepth = 0;

function indent(): string {
    return "  ".repeat(groupDepth);
}

// ---------------------------------------------------------------------------
// Timers
// ---------------------------------------------------------------------------

function time(label?: string): void {
    const key = label ?? "default";
    if (timers.has(key)) {
        console.warn(`Timer '${key}' already exists`);
        return;
    }
    timers.set(key, Date.now());
}

function timeEnd(label?: string): void {
    const key = label ?? "default";
    const start = timers.get(key);
    if (start === undefined) {
        console.warn(`Timer '${key}' does not exist`);
        return;
    }
    timers.delete(key);
    const elapsed = Date.now() - start;
    console.log(`${indent()}${key}: ${elapsed}ms`);
}

function timeLog(label?: string, ...data: unknown[]): void {
    const key = label ?? "default";
    const start = timers.get(key);
    if (start === undefined) {
        console.warn(`Timer '${key}' does not exist`);
        return;
    }
    const elapsed = Date.now() - start;
    if (data.length === 0) {
        console.log(`${indent()}${key}: ${elapsed}ms`);
    } else {
        console.log(`${indent()}${key}: ${elapsed}ms`, ...data);
    }
}

// ---------------------------------------------------------------------------
// Assert
// ---------------------------------------------------------------------------

function assert(condition?: boolean, ...data: unknown[]): void {
    if (condition) {
        return;
    }
    const prefix = `${indent()}Assertion failed`;
    if (data.length === 0) {
        console.error(prefix);
    } else if (typeof data[0] === "string") {
        console.error(`${prefix}: ${data[0]}`, ...data.slice(1));
    } else {
        console.error(prefix, ...data);
    }
}

// ---------------------------------------------------------------------------
// Counters
// ---------------------------------------------------------------------------

function count(label?: string): void {
    const key = label ?? "default";
    const next = (counters.get(key) ?? 0) + 1;
    counters.set(key, next);
    console.log(`${indent()}${key}: ${next}`);
}

function countReset(label?: string): void {
    const key = label ?? "default";
    if (!counters.has(key)) {
        console.warn(`Count for '${key}' does not exist`);
        return;
    }
    counters.set(key, 0);
}

// ---------------------------------------------------------------------------
// Groups
// ---------------------------------------------------------------------------

function group(label?: string): void {
    if (label !== undefined) {
        console.log(`${indent()}${label}`);
    }
    groupDepth++;
}

function groupEnd(): void {
    if (groupDepth > 0) {
        groupDepth--;
    }
}

// ---------------------------------------------------------------------------
// Installation
// ---------------------------------------------------------------------------

export function installConsolePolyfill(): void {
    if (typeof console.time !== "function") {
        console.time = time;
    }
    if (typeof console.timeEnd !== "function") {
        console.timeEnd = timeEnd;
    }
    if (typeof console.timeLog !== "function") {
        console.timeLog = timeLog;
    }
    if (typeof console.assert !== "function") {
        console.assert = assert;
    }
    if (typeof console.count !== "function") {
        console.count = count;
    }
    if (typeof console.countReset !== "function") {
        console.countReset = countReset;
    }
    if (typeof console.group !== "function") {
        console.group = group as typeof console.group;
    }
    if (typeof console.groupCollapsed !== "function") {
        console.groupCollapsed = group as typeof console.groupCollapsed;
    }
    if (typeof console.groupEnd !== "function") {
        console.groupEnd = groupEnd;
    }
}

/** Resets the module-scoped timer, counter and group state. Not exported from the package; unit tests import it from source. */
export function _resetConsolePolyfillState(): void {
    timers.clear();
    counters.clear();
    groupDepth = 0;
}

// Exported for direct unit testing; not re-exported from the package entry point.
const groupCollapsed = group;
export { time, timeEnd, timeLog, assert, count, countReset, group, groupCollapsed, groupEnd };
